const $=s=>document.querySelector(s);let data=null,tab='today';const LS='indiaGuideDataV1';const API='/api/items';
const icons={place:'📍',food:'🍛',transport:'🚆',hotel:'🏨',note:'📝'};
async function load(){const local=localStorage.getItem(LS); if(local){data=JSON.parse(local)}else{data=await fetch('/data.json').then(r=>r.json()); saveLocal()} try{let r=await fetch(API);if(r.ok){let remote=await r.json();if(remote.items?.length)data.items=remote.items}}catch(e){} init()}
function saveLocal(){localStorage.setItem(LS,JSON.stringify(data))}function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function dateObj(s){return new Date(s+'T12:00:00')}function fmt(s){return new Intl.DateTimeFormat('it-IT',{weekday:'short',day:'numeric',month:'short'}).format(dateObj(s))}
function googleUrl(name,city){return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(name+' '+city)}`}
function init(){const cities=[...new Set(data.items.map(x=>x.city).filter(Boolean))].sort();$('#cityFilter').innerHTML='<option value="">Tutte le città</option>'+cities.map(c=>`<option>${esc(c)}</option>`).join('');hero();bind();render()}
function hero(){const now=new Date();const start=dateObj(data.trip.start),end=dateObj(data.trip.end);let d=data.itinerary.find(x=>dateObj(x.date)>=new Date(now.getFullYear(),now.getMonth(),now.getDate())); if(now>end)d=data.itinerary.at(-1);if(d){$('#heroTitle').textContent=d.title;$('#heroSub').textContent=`${fmt(d.date)} · ${d.base}`;let days=Math.ceil((dateObj(d.date)-now)/86400000);$('#countdown').innerHTML=days>0?`<strong>${days}</strong><small>giorni</small>`:'<strong>✦</strong><small>oggi</small>'}}
function bind(){document.querySelectorAll('#tabs button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('#tabs button').forEach(x=>x.classList.toggle('active',x===b));$('#filters').classList.toggle('hidden',tab!=='explore');render()});['search','cityFilter','typeFilter'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',render));$('#addBtn').onclick=()=>openEditor();$('#closeDialog').onclick=()=>$('#editDialog').close();$('#adminBtn').onclick=()=>{loadToken();$('#adminDialog').showModal()};$('#closeAdmin').onclick=()=>$('#adminDialog').close();$('#editForm').onsubmit=e=>{e.preventDefault();upsert()};$('#deleteBtn').onclick=removeItem;$('#exportBtn').onclick=backup;$('#importInput').onchange=restore;$('#syncBtn').onclick=sync}
function card(x){let style=x.photo?`style="background-image:url('${esc(x.photo)}')"`:'';return `<article class="card ${x.type==='transport'?'transport':''}">${x.photo?`<div class="photo" ${style}></div>`:''}<div class="card-body"><div class="meta"><span class="badge">${icons[x.type]||'•'} ${esc(x.type)}</span><span class="badge ${x.status||''}">${x.status==='verify'?'DA VERIFICARE':x.status==='alternative'?'ALTERNATIVA':'CONFERMATO'}</span>${x.city?`<span class="badge">${esc(x.city)}</span>`:''}</div><h3>${esc(x.name)}</h3><p>${esc(x.subtitle||'')}${x.date?` · ${fmt(x.date)}`:''}${x.departure?` · ${esc(x.departure)}${x.arrival?' → '+esc(x.arrival):''}`:''}</p>${x.notes?`<p style="margin-top:6px">${esc(x.notes)}</p>`:''}<div class="actions">${x.maps?`<a href="${esc(x.maps)}" target="_blank" rel="noopener">Apri Maps ↗</a>`:''}<button class="fav ${x.favorite?'on':''}" onclick="toggleFav('${x.id}')">${x.favorite?'♥ Salvato':'♡ Salva'}</button><button onclick="editItem('${x.id}')">Modifica</button></div></div></article>`}
function render(){if(tab==='itinerary')return renderItinerary();let list=data.items;if(tab==='saved')list=list.filter(x=>x.favorite);if(tab==='today'){let candidate=data.itinerary.find(x=>dateObj(x.date)>=new Date(new Date().setHours(0,0,0,0)))||data.itinerary.at(-1); list=list.filter(x=>x.date===candidate.date||x.city&&candidate.base.includes(x.city));}if(tab==='explore'){const q=$('#search').value.toLowerCase().trim(),c=$('#cityFilter').value,t=$('#typeFilter').value;list=list.filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!c||x.city===c)&&(!t||x.type===t))}$('#content').innerHTML=`<div class="section-title"><h2>${tab==='today'?'In evidenza':tab==='saved'?'I tuoi salvati':'Esplora la guida'}</h2><span>${list.length} elementi</span></div>${list.length?`<div class="cards">${list.map(card).join('')}</div>`:'<div class="empty">Nessun elemento in questa sezione.</div>'}`}
function renderItinerary(){$('#content').innerHTML=`<div class="section-title"><h2>Itinerario</h2><span>25 dic → 12 gen</span></div><div class="timeline">${data.itinerary.map(d=>{let dt=dateObj(d.date);return `<div class="day"><div class="datebox"><strong>${dt.getDate()}</strong><small>${dt.toLocaleDateString('it-IT',{month:'short'}).toUpperCase()}</small></div><div class="day-content"><h3>${esc(d.title)}</h3><p>${esc(d.base)}</p></div></div>`}).join('')}</div>`}
window.toggleFav=id=>{let x=data.items.find(i=>i.id===id);x.favorite=!x.favorite;saveLocal();render()};window.editItem=id=>openEditor(data.items.find(i=>i.id===id));
function openEditor(x={}){['itemId','itemName','itemCity','itemSubtitle','itemDate','itemDeparture','itemArrival','itemMaps','itemPhoto','itemNotes'].forEach(k=>$('#'+k).value='');$('#itemType').value=x.type||'place';$('#itemId').value=x.id||'';$('#itemName').value=x.name||'';$('#itemCity').value=x.city||'';$('#itemSubtitle').value=x.subtitle||'';$('#itemDate').value=x.date||'';$('#itemStatus').value=x.status||'confirmed';$('#itemDeparture').value=x.departure||'';$('#itemArrival').value=x.arrival||'';$('#itemMaps').value=x.maps||'';$('#itemPhoto').value=x.photo||'';$('#itemNotes').value=x.notes||'';$('#deleteBtn').style.visibility=x.id?'visible':'hidden';$('#formTitle').textContent=x.id?'Modifica elemento':'Aggiungi elemento';$('#editDialog').showModal()}
function formItem(){let city=$('#itemCity').value.trim(),name=$('#itemName').value.trim();return{id:$('#itemId').value||'u'+Date.now(),type:$('#itemType').value,name,city,subtitle:$('#itemSubtitle').value.trim(),date:$('#itemDate').value,status:$('#itemStatus').value,departure:$('#itemDeparture').value.trim(),arrival:$('#itemArrival').value.trim(),maps:$('#itemMaps').value.trim()||googleUrl(name,city),photo:$('#itemPhoto').value.trim(),notes:$('#itemNotes').value.trim(),favorite:false,visited:false}}
function upsert(){let item=formItem(),i=data.items.findIndex(x=>x.id===item.id);if(i>=0)item={...data.items[i],...item},data.items[i]=item;else data.items.unshift(item);saveLocal();$('#editDialog').close();render();cloudWrite(item,'PUT')}
function removeItem(){let id=$('#itemId').value;if(!id)return;data.items=data.items.filter(x=>x.id!==id);saveLocal();$('#editDialog').close();render();cloudWrite({id},'DELETE')}
function loadToken(){let t=sessionStorage.getItem('indiaAdminToken')||'';$('#adminToken').value=t}async function cloudWrite(item,method){let token=sessionStorage.getItem('indiaAdminToken');if(!token)return;try{let r=await fetch(API,{method,headers:{'content-type':'application/json','authorization':`Bearer ${token}`},body:JSON.stringify(item)});if(!r.ok)console.warn('Cloud sync non riuscita')}catch(e){}}
async function sync(){let token=$('#adminToken').value.trim();sessionStorage.setItem('indiaAdminToken',token);$('#syncStatus').textContent='Sincronizzazione…';try{let r=await fetch(API);if(!r.ok)throw 0;let remote=await r.json();for(const x of data.items){await fetch(API,{method:'PUT',headers:{'content-type':'application/json','authorization':`Bearer ${token}`},body:JSON.stringify(x)})}$('#syncStatus').textContent=`Sincronizzati ${data.items.length} elementi.`}catch(e){$('#syncStatus').textContent='Database cloud non ancora collegato. La guida locale continua a funzionare.'}}
function backup(){let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='india-guida-backup.json';a.click();URL.revokeObjectURL(a.href)}
function restore(e){let f=e.target.files?.[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let v=JSON.parse(r.result);if(!Array.isArray(v.items))throw 0;data=v;saveLocal();init();$('#syncStatus').textContent='Backup importato.'}catch(_){$('#syncStatus').textContent='File di backup non valido.'}};r.readAsText(f)}
load();
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
